import {records,syntax,assessDNS,csvCell,parseCSV} from './core.mjs';
import {queryDNS} from './dns-query.mjs';
import {RULESET,diagnostics,savedMailbox,csvObjects,retryDue,assessOutcome,classifyFailure} from './evidence.mjs';
const $=id=>document.getElementById(id);
let rows=[],filter='all',page=0,running=false,local=false,abort,sourceName='Pasted list',disposable=new Set(),previous=new Map(),outcomes=[];
const typoDomains={'gmial.com':'gmail.com','gamil.com':'gmail.com','gmai.com':'gmail.com','gmail.con':'gmail.com','gmail.co':'gmail.com','hotmial.com':'hotmail.com','hotmai.com':'hotmail.com','outlok.com':'outlook.com','outllook.com':'outlook.com','yaho.com':'yahoo.com','yahoo.con':'yahoo.com'};
const setMessage=(m,error=false)=>{$('message').textContent=m;$('message').classList.toggle('error',error);};
const supSet=()=>new Set($('suppress').value.split(/[\r\n,;]+/).map(v=>v.trim().toLowerCase()).filter(Boolean));
function category(r){if(r.suppressed)return 'suppressed';if(r.duplicate)return 'review';if(r.dns?.status==='invalid'||r.mailbox?.status==='rejected'||r.syntax==='invalid')return 'invalid';if(r.mailbox?.status==='accepted')return 'passed';if(r.syntax==='passed'&&r.dns?.status==='passed'&&!r.flags.length&&!r.probed)return 'passed';return 'review';}
function label(r){if(r.suppressed)return 'Suppressed';if(r.duplicate)return 'Duplicate';if(category(r)==='invalid')return 'Invalid / rejected';if(r.mailbox?.status==='accepted')return 'SMTP accepted';if(r.mailbox?.status==='accepted-unconfirmed')return 'Accepted / catch-all uncertain';if(r.mailbox?.status==='catch-all')return 'Catch-all';if(r.dns?.check_failed||r.mailbox?.check_failed)return 'Check failed';if(category(r)==='passed')return 'Domain passed';return r.dns?.status==='pending'?'Checking...':'Needs review';}
function cell(tr,text,small){const td=document.createElement('td');td.textContent=text;if(small){const el=document.createElement('small');el.textContent=small;td.append(el);}tr.append(td);return td;}
function render(){
 $('retry-due').disabled=running||!local||!rows.some(r=>retryDue(r));renderOutcomes();
 $('result-caption').textContent=rows.length?`Mailbox evidence: ${rows.filter(r=>r.mailbox?.status==='accepted').length} SMTP accepted · ${rows.filter(r=>r.mailbox?.status==='accepted-unconfirmed').length} accepted / catch-all uncertain · ${rows.filter(r=>r.mailbox?.status==='catch-all').length} catch-all · All other inboxes rejected, unknown, or unchecked. Acceptance is not a delivery guarantee.`:'Evidence for every address. No invented confidence scores.';
 $('total').textContent=rows.length;$('passed').textContent=rows.filter(r=>!r.suppressed&&!r.duplicate&&r.dns?.status==='passed').length;$('invalid').textContent=rows.filter(r=>category(r)==='invalid').length;$('review').textContent=rows.filter(r=>['review','suppressed'].includes(category(r))).length;
 const search=$('search').value.toLowerCase();const visible=rows.filter(r=>(filter==='all'||category(r)===filter)&&[r.email,r.reason,r.provider,...r.flags].join(' ').toLowerCase().includes(search));
 const pages=Math.max(1,Math.ceil(visible.length/50));page=Math.min(page,pages-1);$('results').replaceChildren();
 for(const r of visible.slice(page*50,page*50+50)){
  const tr=document.createElement('tr');cell(tr,r.email||'(empty address)',r.checked?new Date(r.checked).toLocaleString():'');const status=cell(tr,'');const badge=document.createElement('span');badge.className='badge '+category(r);badge.textContent=label(r);status.append(badge);
  cell(tr,r.dns?.status||'Not checked',r.dns?.hosts?.slice(0,2).join(', '));cell(tr,r.mailbox?.recipient_status||r.mailbox?.status||'Not checked',r.mailbox?.rule);cell(tr,r.mailbox?.catchall_status||'not_tested');cell(tr,r.provider||'Not imported','Historical evidence');
  cell(tr,[...r.flags,r.reason,diagnostics(r.mailbox||{}),r.origin==='saved'?'Saved evidence reviewed; no new probe':'',r.retry_at?'Retry after '+new Date(r.retry_at).toLocaleString():'',assessOutcome(r,outcomes).outcome!=='unobserved'?assessOutcome(r,outcomes).assessment:''].filter(Boolean).join(' · ')).className='flags';$('results').append(tr);
 }
 $('empty').hidden=visible.length>0;$('empty').querySelector('h3').textContent=rows.length?'No matching addresses.':'A little clarity for every address.';$('empty').querySelector('p').textContent=rows.length?'Choose another filter or search term.':'Your results will appear here after you run a check.';
 $('row-count').textContent=`${visible.length} of ${rows.length} addresses`;$('page-label').textContent=visible.length?`${page+1} / ${pages}`:'';$('previous').disabled=page===0;$('next').disabled=page>=pages-1;$('export').disabled=!rows.length||running;
}
async function domainCheck(domain,signal){try{const mx=await queryDNS(domain,'MX',{signal});let result;if(mx.Status!==0||(mx.Answer||[]).some(x=>x.type===15))result=assessDNS(mx);else{const [a,aaaa]=await Promise.allSettled([queryDNS(domain,'A',{signal}),queryDNS(domain,'AAAA',{signal})]);result=assessDNS(mx,a.status==='fulfilled'?a.value:{Status:2},aaaa.status==='fulfilled'?aaaa.value:{Status:2});}return {...result,resolver:mx.resolver,check_failed:result.status==='unknown'};}catch(e){return {status:'unknown',reason:signal.aborted?'Check cancelled':e.message,check_failed:true,hosts:[]};}}
function isDisposable(domain){const p=domain.split('.');return p.some((_,i)=>i<p.length-1&&disposable.has(p.slice(i).join('.')));}
async function run(){
 let input;try{if($('emails').value.length>5*1024*1024)throw Error('Use a list under 5 MB.');input=records($('emails').value);if(!input.length)throw Error('Add at least one email address.');if(input.length>5000)throw Error('Please split your list into batches of 5,000 rows or fewer.');}catch(e){return setMessage(e.message,true);}
 input=input.map(r=>({...r,provider:r.provider||previous.get(r.email.toLowerCase())||''}));
 running=true;abort=new AbortController();const signal=abort.signal;const probing=local&&$('smtp').checked;const suppressed=supSet(),seen=new Set(),cache=new Map();filter='all';page=0;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));
 rows=input.map((r,i)=>{const key=r.email.toLowerCase(),s=syntax(r.email);const duplicate=seen.has(key);seen.add(key);const flags=[];if(s.role)flags.push('Role address');if(s.disposable||(s.ok&&isDisposable(s.domain)))flags.push('Known disposable domain');if(typoDomains[s.domain])flags.push('Possible typo: '+typoDomains[s.domain]);if(duplicate)flags.push('Duplicate (case-insensitive match)');return {...r,id:i,flags,duplicate,suppressed:suppressed.has(key),syntax:s.ok?'passed':s.unknown?'unsupported':'invalid',domain:s.domain,reason:s.ok?'':s.reason,dns:{status:'pending'},mailbox:{status:'not checked'},probed:false};});
 $('saved-file').disabled=true;$('outcome-file').disabled=true;$('verify-button').disabled=true;$('previous-file').disabled=true;$('file').disabled=true;$('emails').disabled=true;$('smtp').disabled=true;$('apply-suppress').disabled=true;$('suppress').disabled=true;$('demo').disabled=true;$('stop').hidden=false;$('progress-track').hidden=false;$('progress').style.width='0%';
 let completed=0,next=0;render();
 async function worker(){while(next<rows.length&&!signal.aborted){const r=rows[next++];try{
  if(r.suppressed){r.dns={status:'not checked'};r.reason='Matches your suppression list; no lookup or probe performed';}
  else if(r.duplicate){r.dns={status:'not checked'};r.reason='Duplicate row; no repeated lookup or probe';}
  else if(r.syntax!=='passed'){r.dns={status:'not checked'};}
  else{if(!cache.has(r.domain))cache.set(r.domain,domainCheck(r.domain,signal));r.dns=await cache.get(r.domain);r.reason=r.dns.reason;
   if(probing&&!signal.aborted&&r.dns.status==='passed'&&!r.flags.includes('Known disposable domain')){r.probed=true;try{const response=await fetch('/api/probe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:r.email}),signal});const result=await response.json();if(!response.ok)throw Error(result.error||'Local verifier unavailable');r.mailbox=result;r.reason=result.reason;r.attempts=1;r.retry_at=result.retryable?new Date(Date.now()+900000).toISOString():'';}catch(e){r.mailbox={status:'unknown',check_failed:true};r.reason=signal.aborted?'Probe cancelled':e.message;}}
  }
 }catch(e){r.reason=e.message;r.dns={status:'unknown'};}r.checked=new Date().toISOString();completed++;$('progress').style.width=`${100*completed/rows.length}%`;setMessage(`Checking ${completed.toLocaleString()} of ${rows.length.toLocaleString()} addresses${probing?' · Mailbox probes may take up to 50 seconds including a backup server.':''}`);render();}}
 try{await Promise.all(Array.from({length:probing?2:4},worker));}finally{
  for(const r of rows)if(r.dns.status==='pending'){r.dns={status:'not checked'};r.reason='Cancelled before check';}
  running=false;$('saved-file').disabled=false;$('outcome-file').disabled=false;$('verify-button').disabled=false;$('previous-file').disabled=false;$('file').disabled=false;$('emails').disabled=false;$('smtp').disabled=!local;$('apply-suppress').disabled=false;$('suppress').disabled=false;$('demo').disabled=false;$('stop').hidden=true;render();const failed=rows.filter(r=>r.dns?.check_failed||r.mailbox?.check_failed).length;setMessage(signal.aborted?`Stopped. ${completed} rows processed. Export includes unchecked rows with their status.`:`Finished · ${completed.toLocaleString()} rows processed · ${failed} checks failed. ${failed?'Failed checks are inconclusive, not invalid mailboxes.':'Domain checks alone do not confirm inbox existence.'}`,failed===rows.length);
 }
}
$('verify-button').onclick=run;$('stop').onclick=()=>{abort?.abort();setMessage('Stopping checks…');};
async function loadFile(file){if(!file)return;if(file.size>5*1024*1024)return setMessage('Please use a CSV smaller than 5 MB.',true);try{const text=await file.text();const parsed=records(text);if(parsed.length>5000)throw Error('Use batches of 5,000 rows or fewer.');$('emails').value=text;$('filename').textContent=file.name;sourceName=file.name;setMessage(`${parsed.length.toLocaleString()} rows loaded. Click Verify emails to start.`);}catch(e){setMessage(e.message,true);}}
$('file').onchange=e=>loadFile(e.target.files[0]);$('emails').oninput=()=>{sourceName='Pasted list';$('filename').textContent='Drop your CSV here';};
$('dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click();}};
for(const event of ['dragover','dragleave','drop'])$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.toggle('dragover',event==='dragover');if(event==='drop'&&!running)loadFile(e.dataTransfer.files[0]);});
$('demo').onclick=()=>{$('emails').value='email,status\nhello@gmail.com,\ninvalid-address,\ninfo@example.com,\nname@mailinator.com,\nhello@gmail.com,\nsomeone@gmial.com,catch-all\nuser@this-domain-does-not-exist-mailcheck.invalid,';sourceName='Sample list';setMessage('Sample loaded. These are examples, not your contacts.');};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=0;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();});
$('search').oninput=()=>{page=0;render();};$('previous').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};
$('apply-suppress').onclick=()=>{const s=supSet();$('suppress-count').textContent=`${s.size} addresses`;rows.forEach(r=>{r.suppressed=s.has(r.email.toLowerCase());});render();setMessage(`Suppression list applied to ${rows.filter(r=>r.suppressed).length} current rows. Previously completed checks remain visible.`);};
$('export').onclick=()=>{
 const data=rows.map(r=>({email:r.email,result:label(r),syntax:r.syntax,domain_status:r.dns?.status,mail_servers:r.dns?.hosts?.join('; '),mailbox_status:r.mailbox?.status,recipient_status:r.mailbox?.recipient_status,catchall_status:r.mailbox?.catchall_status,rule:r.mailbox?.rule,ruleset:RULESET,imported_status:r.provider,duplicate:r.duplicate,suppressed:r.suppressed,flags:r.flags.join('; '),evidence:r.reason,diagnostics:diagnostics(r.mailbox||{}),checked_at:r.checked,reviewed_at:r.reviewed_at,evidence_origin:r.origin||'live',smtp_host:r.mailbox?.host,smtp_tls:r.mailbox?.encrypted,recipient_reply:r.mailbox?.recipient_reply,catchall_reply:r.mailbox?.catchall_reply,check_failed:Boolean(r.dns?.check_failed||r.mailbox?.check_failed),dns_resolver:r.dns?.resolver,retryable:r.mailbox?.retryable,attempts:r.attempts||0,retry_at:r.retry_at,attempt_history:JSON.stringify(r.mailbox?.attempt_history||[]),prior_checks:JSON.stringify(r.prior_attempts||[]),observed_outcome:assessOutcome(r,outcomes).outcome,outcome_assessment:assessOutcome(r,outcomes).assessment}));
 const headers=Object.keys(data[0]);const text=[headers,...data.map(r=>headers.map(k=>r[k]))].map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mailcheck-results-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
};
function renderOutcomes(){
 const scored=rows.filter(r=>!r.suppressed&&!r.duplicate&&r.mailbox?.status==='accepted').map(r=>assessOutcome(r,outcomes));const observed=scored.filter(r=>['reply','delivered','hard_bounce'].includes(r.outcome));const bounces=observed.filter(r=>r.outcome==='hard_bounce').length;
 $('outcome-summary').textContent=outcomes.length?`Among ${scored.length} SMTP-accepted addresses: ${observed.length} have usable subsequent outcomes, including ${bounces} hard bounces. ${observed.length?'Observed hard-bounce fraction: '+(100*bounces/observed.length).toFixed(1)+'%. ':''}This selected sample does not establish overall accuracy. Old or conflicting outcomes are excluded.`:'No outcome data imported; accuracy is not measured. No bounce is not proof of delivery.';
}
async function fileText(file){if(!file||file.size>5242880)throw Error('Select a CSV under 5 MB.');return file.text();}
$('saved-file').onchange=async e=>{if(running)return;try{const source=csvObjects(await fileText(e.target.files[0]),parseCSV);if(!source.length||source.length>5000||!('mailbox_status' in source[0])||!('checked_at' in source[0]))throw Error('Import a Mailcheck export, up to 5,000 rows.');rows=source.map((r,i)=>{const mailbox=savedMailbox(r);return {id:i,email:r.email,provider:previous.get(r.email.toLowerCase())||r.imported_status||'',syntax:r.syntax,dns:{status:r.domain_status,hosts:(r.mail_servers||'').split('; ').filter(Boolean),resolver:r.dns_resolver},flags:(r.flags||'').split('; ').filter(Boolean),duplicate:r.duplicate==='true',suppressed:r.suppressed==='true'||supSet().has(r.email.toLowerCase()),mailbox,probed:!['not checked','not_checked',''].includes(r.mailbox_status||''),origin:'saved',checked:r.checked_at,reviewed_at:new Date().toISOString(),reason:mailbox.reason,attempts:Number(r.attempts)||1,retry_at:r.retry_at||(mailbox.retryable&&Number.isFinite(Date.parse(r.checked_at))?new Date(Date.parse(r.checked_at)+900000).toISOString():'')};});filter='all';page=0;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));render();setMessage(`${rows.length} saved results reviewed using rules ${RULESET}. No new lookup or SMTP probe performed. Original check times retained.`);}catch(e){setMessage(e.message,true);}};
$('outcome-file').onchange=async e=>{if(running)return;try{const source=csvObjects(await fileText(e.target.files[0]),parseCSV);if(!source.length||source.length>5000||source.some(r=>!syntax(r.email).ok||!['reply','delivered','hard_bounce','soft_bounce'].includes(r.outcome)||!/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(r.observed_at)||!Number.isFinite(Date.parse(r.observed_at))||Date.parse(r.observed_at)>Date.now()))throw Error('Use email,outcome,observed_at columns. Outcomes: reply, delivered, hard_bounce, soft_bounce. Dates: ISO timestamps with timezone, not future dates.');outcomes=source;render();setMessage(`${outcomes.length} outcome events imported locally. Only events after each check are evaluated.`);}catch(e){setMessage(e.message,true);}};
$('retry-due').onclick=async()=>{
 if(running||!local)return;const pending=rows.filter(r=>retryDue(r));if(!pending.length)return;running=true;abort=new AbortController();const signal=abort.signal;const controls=['verify-button','file','emails','previous-file','saved-file','outcome-file','smtp','suppress','apply-suppress','demo'];controls.forEach(id=>$(id).disabled=true);$('stop').hidden=false;let next=0,done=0;render();
 const worker=async()=>{while(next<pending.length&&!signal.aborted){const r=pending[next++];r.prior_attempts=[...(r.prior_attempts||[]),{checked_at:r.checked,status:r.mailbox.status,reason:r.reason}];try{const response=await fetch('/api/probe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:r.email}),signal});const result=await response.json();if(!response.ok)throw Error(result.error||'Verifier unavailable');r.mailbox=result;}catch(e){r.mailbox=classifyFailure(e);}r.checked=new Date().toISOString();r.origin='live';r.reviewed_at='';r.attempts=(r.attempts||1)+1;r.retry_at=r.mailbox.retryable&&r.attempts<3?new Date(Date.now()+900000).toISOString():'';r.reason=r.mailbox.reason;done++;setMessage(`Retried ${done} of ${pending.length} due checks`);render();}};
 try{await Promise.all([worker(),worker()]);}finally{running=false;controls.forEach(id=>$(id).disabled=false);$('smtp').disabled=!local;$('stop').hidden=true;render();setMessage(`Retried ${done} due checks. Successful checks were not repeated.`);}
};
setInterval(()=>{if(!running)$('retry-due').disabled=!local||!rows.some(r=>retryDue(r));},30000);
try{const response=await fetch('/disposable-domains.txt');if(response.ok)disposable=new Set((await response.text()).split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.startsWith('#')));}catch{/* Built-in common-domain checks remain available. */}
if(location.hostname==='127.0.0.1')try{const res=await fetch('/api/health');const data=await res.json();if(data.smtp){local=true;$('smtp').disabled=false;$('smtp-help').textContent='Attempts recipient checks without sending a message';$('engine').textContent='● Local verifier v4 ready';}}catch{}
render();

$('previous-file').onchange=async e=>{if(running)return setMessage('Wait for the current check to finish before importing previous results.',true);const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)return setMessage('Previous-results file must be under 5 MB.',true);try{const entries=records(await file.text());if(entries.length>5000)throw Error('Use up to 5,000 previous results.');const imported=entries.filter(r=>r.email&&r.provider);if(!imported.length)throw Error('No statuses found. Import the original Hunter CSV with email and status columns.');previous=new Map(imported.map(r=>[r.email.toLowerCase(),r.provider]));rows.forEach(r=>{r.provider=previous.get(r.email.toLowerCase())||r.provider;});$('previous-count').textContent=previous.size+' previous statuses loaded';render();setMessage('Previous results matched by email. These are historical labels, not fresh mailbox confirmations.');}catch(e){setMessage(e.message,true);}};
